<script setup>
import{onMounted,reactive,ref}from'vue';import{request}from'../api';const docs=ref([]),error=ref('');const hex=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');const form=reactive({documentNo:'DOC-'+Date.now(),name:'企业管理制度.pdf',owner:'行政部',classification:'INTERNAL',sizeBytes:2048,changeNote:'初始版本'});async function load(){docs.value=await request('/api/core/drive/documents')}async function create(){try{await request('/api/core/drive/documents',{method:'POST',body:JSON.stringify({...form,checksum:hex()})});form.documentNo='DOC-'+Date.now();await load()}catch(e){error.value=e.message}}async function version(d){try{await request(`/api/core/drive/documents/${d.id}/versions`,{method:'POST',body:JSON.stringify({checksum:hex(),sizeBytes:4096,changeNote:'工作台修订版本'})});await load()}catch(e){error.value=e.message}}async function share(d){try{const s=await request(`/api/admin/core/drive/documents/${d.id}/shares`,{method:'POST',body:JSON.stringify({expiresInHours:24,maxDownloads:5,password:['CONFIDENTIAL','SECRET'].includes(d.classification)?'demo-pass':''})});alert(`安全共享令牌：${s.token}`)}catch(e){error.value=e.message}}onMounted(load)
</script><template><section class="head"><span>SECURE CONTENT</span><h3>受控文档空间</h3><p>版本不可变、哈希去重、精细分级与受限共享组成文档安全基线。</p></section><p v-if="error" class="err">{{error}}</p><form class="create" @submit.prevent="create"><input v-model="form.documentNo"><input v-model="form.name"><input v-model="form.owner"><select v-model="form.classification"><option>PUBLIC</option><option>INTERNAL</option><option>CONFIDENTIAL</option><option>SECRET</option></select><button>上传首版</button></form><section class="cards"><article v-for="d in docs" :key="d.id"><div class="file">PDF</div><div><code>{{d.documentNo}}</code><h4>{{d.name}}</h4><p>{{d.owner}} · {{d.classification}} · V{{d.currentVersion}}</p></div><span>{{d.status}}</span><div><button @click="version(d)">新增版本</button><button @click="share(d)">安全共享</button></div></article></section></template>
<style scoped>.head,.create,.cards{background:#fff;border:1px solid #dce2df;margin-top:20px;padding:24px}.head span{font-size:11px;letter-spacing:.15em;color:#a56c24}.head h3{margin:6px 0}.head p{margin:0;color:#68777c}.create{display:grid;grid-template-columns:1fr 2fr 1fr 1fr auto;gap:10px}.create input,.create select{padding:10px;border:1px solid #ccd6d2}.create button,.cards button{border:0;background:#235a74;color:#fff;padding:9px 12px}.cards article{display:grid;grid-template-columns:50px 1fr 100px auto;gap:15px;align-items:center;padding:14px 0;border-top:1px solid #edf0ef}.file{height:50px;display:grid;place-items:center;background:#edf2f0;color:#235a74;font-weight:800}.cards h4{margin:4px 0}.cards p{margin:0;color:#68777c}.cards button{margin-left:5px}.err{color:#a03f38}@media(max-width:800px){.create,.cards article{grid-template-columns:1fr}}</style>
